from numba.core import types
from numba.np import random as npr
from numba import njit
import numpy as np

@njit
def test_binomial_301():
    gen = npr.create_np_random_state(npr.PCG64, seed=0)
    result = npr.generator_binomial(gen, 301, 0.1, 3)
    return result

try:
    result = test_binomial_301()
    for i, val in enumerate(result):
        probe('binomial_301_sample_{}'.format(i), float(val))
except Exception as e:
    probe('error', float(np.nan))

